/**
 * Small QA fixture demonstrating the storyboard compiler with genuine 3D
 * objects. NOT a topic preset or output of Gemini.
 *
 * Every position track of cargo, actor and platform is generated by the
 * story compiler, not authored below.
 */
import { normalizeSceneProgram, type ProgramSource } from '../score';
import { compileStoryEvents } from './events';
import { compileStoryMotion, type StoryMotionBindings } from './choreographer';

export const sampleSources: ProgramSource[]=[
  {sourceId:'s1',duration:4,
   text:'O trabalhador pega um saco de cimento e leva até a plataforma.'},
  {sourceId:'s2',duration:2.5,
   text:'Ele apoia o saco na plataforma e liga o motor.'},
  {sourceId:'s3',duration:7.5,
   text:'O motor levanta a plataforma com o mesmo saco de cimento até o quinto andar.'}
];

export function sampleStoryProposal() {
  return {
    version:1,duration:14,
    entities:[
      {id:'base',kind:'place'},
      {id:'plataforma',kind:'place'},
      {id:'andar_superior',kind:'place'},
      {id:'trabalhador',kind:'actor',at:'base'},
      {id:'saco',kind:'prop',at:'base'},
      {id:'elevador',kind:'prop',at:'plataforma'},
      {id:'motor',kind:'mechanism',at:'plataforma',controls:['elevador']}
    ],
    events:[
      {id:'apresentar',sourceId:'s1',start:0,end:.45,action:'focus',subject:'saco',
       evidence:'um saco de cimento',purpose:'Mostrar a carga que será transportada'},
      {id:'pegar',sourceId:'s1',start:.45,end:1.1,action:'pick_up',subject:'saco',actor:'trabalhador',
       evidence:'pega um saco de cimento',purpose:'Mostrar o mesmo saco sair do chão'},
      {id:'levar',sourceId:'s1',start:1.1,end:4,action:'carry',subject:'saco',actor:'trabalhador',
       destination:'plataforma',dependsOn:['pegar'],
       evidence:'leva até a plataforma',purpose:'Transportar o mesmo saco sem criar cópias'},
      {id:'apoiar',sourceId:'s2',start:4,end:5.1,action:'put_down',
       subject:'saco',actor:'trabalhador',destination:'plataforma',support:'elevador',
       evidence:'apoia o saco na plataforma',purpose:'Exibir a carga apoiada no elevador'},
      {id:'ligar',sourceId:'s2',start:5.1,end:6.5,action:'activate',subject:'motor',actor:'trabalhador',
       evidence:'liga o motor',purpose:'Ligar o mecanismo antes de iniciar o içamento'},
      {id:'subir',sourceId:'s3',start:6.5,end:12.3,action:'operate',subject:'elevador',
       mechanism:'motor',destination:'andar_superior',dependsOn:['ligar'],
       evidence:'levanta a plataforma com o mesmo saco de cimento',
       purpose:'Plataforma e o mesmo saco sobem juntos quando o motor opera'},
      {id:'mostrar-resultado',sourceId:'s3',start:12.3,end:14,action:'focus',subject:'saco',
       evidence:'até o quinto andar',dependsOn:['subir'],
       purpose:'Revelar o saco na posição final alcançada pelo elevador'}
    ]
  };
}

const root=(id:string,position:number[],extra:Record<string,unknown>={})=>
  ({id,kind:'group',contextSourceId:'s1',position,...extra});
const mesh=(id:string,shape:string,size:number[],color:string,position:number[],extra:Record<string,unknown>={})=>
  ({id,kind:'mesh',contextSourceId:'s1',position,
    geometry:{shape,size},color,...extra});
const box=(id:string,size:number[],color:string,position:number[],parent?:string)=>
  mesh(id,'box',size,color,position,parent?{parent}:{});

export function sampleSceneGeometry() {
  const nodes:any[]=[
    box('floor',[90,.16,90],'#C1B69B',[0,-.11,0]),
    box('rear-wall',[8,6,.18],'#B7C6CF',[0,3,-2.4]),
    box('workshop-window',[1.9,1.7,.20],'#A3D6E9',[-2,3.25,-2.27]),
    box('workshop-frame',[2.2,.11,.22],'#FFFFFF',[-2,2.36,-2.2]),
    box('building-left',[.25,7,.25],'#8B9B9F',[-1.08,3.5,-.60]),
    box('building-right',[.25,7,.25],'#8B9B9F',[1.08,3.5,-.60]),
    box('building-crossbar',[2.45,.2,.25],'#8B9B9F',[0,7,-.60]),
    box('building-upper-floor',[3.4,.22,1.8],'#B8C5CE',[0,5.7,-.67]),
    box('building-railing',[2.9,.12,.12],'#F4D967',[0,6.36,.25]),
    root('trabalhador',[-2.6,0,.15]),
    root('saco',[-2.25,.19,.15]),
    mesh('sack-body','box',[.76,.33,.46],'#EBE6D7',[0,0,0],{parent:'saco',
      geometry:{shape:'box',size:[.76,.33,.46],bevel:.11}}),
    mesh('sack-green-band','box',[.17,.34,.47],'#3F9871',[0,0,.003],{parent:'saco'}),
    root('elevador',[0,.42,0]),
    box('platform-base',[1.65,.18,1.18],'#B57942',[0,0,0],'elevador'),
    box('platform-rail-a',[.075,.60,1.12],'#47768C',[-.75,.37,0],'elevador'),
    box('platform-rail-b',[.075,.60,1.12],'#47768C',[.75,.37,0],'elevador'),
    box('platform-rear',[1.65,.62,.08],'#5A7188',[0,.37,-.52],'elevador'),
    root('motor',[2.20,.30,-.05]),
    mesh('motor-shell','cylinder',[.49,.49,.96],'#2464B1',[0,.52,0],{parent:'motor',rotation:[0,0,Math.PI/2]}),
    box('motor-foot',[1.50,.19,1.16],'#374B60',[0,0,0],'motor'),
    mesh('motor-front-cap','cylinder',[.51,.51,.11],'#173D71',[.52,.52,0],
      {parent:'motor',rotation:[0,0,Math.PI/2]}),
    root('drive-gear',[.96,.78,.18],{parent:'motor'}),
    mesh('gear-wheel','cylinder',[.60,.60,.17],'#E4B648',[0,0,0],
      {parent:'drive-gear',rotation:[Math.PI/2,0,0]}),
    mesh('gear-rotor-mark','box',[.82,.14,.19],'#A24E28',[0,0,.18],{parent:'drive-gear'}),
    mesh('gear-rotor-mark-2','box',[.42,.09,.19],'#F1D06D',[0,0,.21],
      {parent:'drive-gear',rotation:[0,0,Math.PI/2]}),
    box('motor-link-shaft',[.46,.13,.14],'#7B8387',[.48,.80,-.02],'motor'),
    mesh('pulley-wheel','torus',[.26,.07],'#DA7D40',[0,7,-.34]),
    mesh('pulley-highlight','box',[.46,.06,.10],'#FCE6A2',[0,7,-.25]),
    box('upper-title-plate',[1.9,.18,.18],'#E6A74D',[0,5.97,-.36]),
  ];
  // Use the shared articulated actor rather than hand-modeling a duplicate.
  nodes[nodes.findIndex(n=>n.id==='trabalhador')] = {
    id:'trabalhador',kind:'actor',contextSourceId:'s1',
    position:[-2.6,0,.15],color:'#EAC147'
  };
  return normalizeSceneProgram({
    version:1, background:'#A8DAEA',nodes,
    // A small independent ambient pulley marker keeps the existing SceneProgram
    // validator satisfied; NO cargo, actor, pallet or motor tracks are authored.
    tracks:[{node:'pulley-highlight',channel:'rotation',interpolation:'linear',
      keys:[
        {sourceId:'s3',phase:0,value:[0,0,0]},
        {sourceId:'s3',phase:.78,value:[0,0,12.0]}
      ]}],contacts:[],
    shots:[
      {sourceId:'s1',subjects:['trabalhador','saco','elevador'],
        azimuth:.47,endAzimuth:.47,elevation:.12,distance:1.10},
      {sourceId:'s2',subjects:['saco','elevador','motor'],
        azimuth:.45,endAzimuth:.45,elevation:.13,distance:1.10},
      {sourceId:'s3',subjects:['elevador','saco','building-upper-floor'],
        azimuth:.40,endAzimuth:.40,elevation:.17,distance:1.13}
    ]
  },sampleSources);
}

export const sampleBindings:StoryMotionBindings = {
  entityNodes:{
    trabalhador:'trabalhador',saco:'saco',
    elevador:'elevador',motor:'motor'
  },
  placeAnchors:{
    base:[-2.6,0,0],plataforma:[0,0,0],andar_superior:[0,4.2,0]
  },
  heldOffsets:{saco:[.28,1.25,.3]},
  supportOffsets:{saco:[0,.43,0]},
  motorVisuals:{motor:{node:'drive-gear',axis:'z',revolutions:4.6}}
};
export function sampleCompiledFilm() {
  const storyboard=compileStoryEvents(sampleStoryProposal(),sampleSources);
  return {storyboard,...compileStoryMotion(storyboard,sampleSceneGeometry(),sampleSources,sampleBindings)};
}
